CREATE TABLE editorial_pack_compatibility_evaluations (id INTEGER PRIMARY KEY AUTOINCREMENT, evaluation_id TEXT NOT NULL UNIQUE, import_id TEXT NOT NULL, pack_row_id INTEGER, compatibility_result_id INTEGER, canonical_pack_hash TEXT NOT NULL, trusted_profile_id TEXT NOT NULL, trusted_profile_version TEXT NOT NULL, canonical_profile_hash TEXT NOT NULL, engine_version_used TEXT NOT NULL, machine_contract_fingerprint TEXT NOT NULL, evaluator_contract_version TEXT NOT NULL, adapter_set_fingerprint TEXT NOT NULL, capability_fingerprint TEXT NOT NULL, context_fingerprint TEXT NOT NULL, compatibility_outcome TEXT NOT NULL CHECK(compatibility_outcome IN ('DATA_COMPATIBLE','ADAPTER_REQUIRED','ENGINE_UPGRADE_REQUIRED','INVALID','BLOCKED')), reason_code TEXT NOT NULL, blocker_details TEXT NOT NULL DEFAULT '', evaluated_at INTEGER NOT NULL, FOREIGN KEY(import_id) REFERENCES editorial_pack_imports(import_id) ON DELETE RESTRICT, FOREIGN KEY(pack_row_id) REFERENCES editorial_packs(id) ON DELETE RESTRICT, FOREIGN KEY(compatibility_result_id) REFERENCES editorial_pack_compatibility_results(id) ON DELETE RESTRICT)
