' AND parent_record_identity IS NULL) OR (node_kind='CHILD' AND parent_record_identity IS NOT NULL)), FOREIGN KEY(authoritative_run_identity) REFERENCES editorial_authoritative_run_declarations(declaration_identity) ON DELETE RESTRICT, FOREIGN KEY(project_revision_identity) REFERENCES editorial_project_revisions(revision_identity) ON DELETE RESTRICT, FOREIGN KEY(input_scope_snapshot_identity) REFERENCES editorial_input_scope_snapshots(scope_snapshot_identity) ON DELETE RESTRICT, FOREIGN KEY(compatibility_evaluation_id) REFERENCES editorial_pack_compatibility_evaluations(evaluation_id) ON DELETE RESTRICT, FOREIGN KEY(parent_record_identity) REFERENCES editorial_lineage_records(record_identity) ON DELETE RESTRICT)
